async function followGmail(id){const info=document.querySelector('#gmail-info'),cancel=document.querySelector('#gmail-cancel');cancel.hidden=false;try{for(;;){const result=await api('/api/gmail/connect-status',{task_id:id});if(result.status==='complete'){sessionStorage.removeItem('waypoint-gmail-connect');await gmailStatus();break;}if(result.status==='failed'){sessionStorage.removeItem('waypoint-gmail-connect');throw new Error(result.error || 'Connection failed');}await new Promise(resolve=>setTimeout(resolve,1000));}}catch(e){info.textContent=e.message;if(e.message==='Gmail connection not found')sessionStorage.removeItem('waypoint-gmail-connect');}finally{cancel.hidden=true;}}
document.querySelector('#gmail-connect').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),file=form.elements.client.files[0];if(!file || file.size>32768){notify('Choose an OAuth JSON file no larger than 32 KiB');return;}button.disabled=true;try{const result=await api('/api/gmail/connect-start',{client_json:await file.text()});sessionStorage.setItem('waypoint-gmail-connect',result.task_id);document.querySelector('#gmail-info').textContent='Complete Google consent in your browser.';await followGmail(result.task_id);}catch(e){notify(e.message);}finally{button.disabled=false;form.reset();}});
document.querySelector('#gmail-cancel').addEventListener('click',async()=>{try{await api('/api/gmail/connect-cancel',{task_id:sessionStorage.getItem('waypoint-gmail-connect')});}catch(e){notify(e.message);}});
document.querySelector('#gmail-disconnect').addEventListener('click',async()=>{try{await api('/api/gmail/disconnect',{});await gmailStatus();notify('Saved Gmail credentials removed locally.');}catch(e){notify(e.message);}});
const pendingGmail=sessionStorage.getItem('waypoint-gmail-connect');if(pendingGmail)followGmail(pendingGmail);else gmailStatus().catch(()=>{});

async function storageStatus(){const result=await api('/api/storage/status',{});document.querySelector('#storage-info').textContent=`Active: ${result.active || 'unavailable'} · Configured: ${result.configured}`;document.querySelector('#storage-form').elements.path.value=result.configured;}
document.querySelector('#storage-form').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');button.disabled=true;try{await api('/api/storage/configure',{path:form.elements.path.value.trim()});await storageStatus();notify('Folder saved. Restart Waypoint to use it; existing data stays where it is.');}catch(e){notify(e.message);}finally{button.disabled=false;}});
storageStatus().catch(e=>{document.querySelector('#storage-info').textContent=e.message;});

const pendingConversion=sessionStorage.getItem('waypoint-conversion');if(pendingConversion)followConversion(pendingConversion).catch(e=>{if(e.message==='Conversion not found')sessionStorage.removeItem('waypoint-conversion');notify(e.message);});

try{const pending=JSON.parse(sessionStorage.getItem('waypoint-form-inspection') || 'null');if(pending)followFormInspection(pending.task,pending.job).then(()=>{if(pending.queued&&reviewQueue[0]===pending.job){reviewQueue.shift();saveReviewQueue();}}).catch(e=>{if(e.message==='Form inspection not found')sessionStorage.removeItem('waypoint-form-inspection');notify(e.message);}).finally(()=>{reviewQueueBusy=false;renderReviewQueue();});}catch(_){sessionStorage.removeItem('waypoint-form-inspection');reviewQueueBusy=false;}

function updateCandidateSelection(){document.querySelector('#candidate-selected-count').textContent=`${selectedCandidates.size} listings selected`;document.querySelector('#candidate-batch-start').disabled=candidateBatchRunning || (!candidateBatch && (selectedCandidates.size===0 || selectedCandidates.size>10));}
function webCandidate(item){const card=element('article','','web-candidate'),link=element('a',item.title),label=element('label','','candidate-select'),checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=selectedCandidates.has(item.url);checkbox.setAttribute('aria-label',`Select listing ${item.title}`);checkbox.addEventListener('change',()=>{if(checkbox.checked)selectedCandidates.set(item.url,{url:item.url,title:item.title});else selectedCandidates.delete(item.url);updateCandidateSelection();});label.append(checkbox,document.createTextNode(' Select for inspection'));card.append(label);link.href=item.url;link.target='_blank';link.rel='noopener noreferrer';card.append(link,element('p',item.snippet),element('p','Unverified link; inspect or open the page and review before applying.','footnote'));const inspect=element('button','Inspect and add');inspect.type='button';inspect.addEventListener('click',async()=>{inspect.disabled=true;try{const started=await api('/api/listing-inspect/start',{url:item.url});sessionStorage.setItem('waypoint-listing-inspection',started.task_id);notify('Inspecting listing in the background');await followListingInspection(started.task_id);}catch(e){notify(e.message);}finally{inspect.disabled=false;}});card.append(inspect);const add=element('button','Enter details manually');add.type='button';add.addEventListener('click',()=>{const form=document.querySelector('#manual-job-form');form.closest('details').open=true;form.elements.url.value=item.url;form.elements.title.value=item.title;form.elements.description.value=item.snippet;form.elements.employer.focus();form.scrollIntoView({behavior:'smooth'});});card.append(add);return card;}
async function followWebSearch(id){const panel=document.querySelector('#web-search-results');let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/web-search/status',{task_id:id});}while(result.status==='running');sessionStorage.removeItem('waypoint-web-search');if(result.status!=='complete')throw new Error(result.error || 'Web search failed');const data=result.data;panel.replaceChildren(element('p',`${data.results.length} candidate links from ${data.results_examined} results${data.limited?' (limited to 30 displayed)':''}. ${data.unresponsive_engines} engines reported unavailable.`));for(const item of data.results)panel.append(webCandidate(item));}
document.querySelector('#web-search').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),panel=document.querySelector('#web-search-results');button.disabled=true;panel.replaceChildren(element('p','Searching…'));try{const result=await api('/api/web-search/start',{provider:form.elements.provider.value,query:form.elements.query.value});sessionStorage.setItem('waypoint-web-search',result.task_id);await followWebSearch(result.task_id);}catch(e){panel.replaceChildren(element('p',e.message));}finally{button.disabled=false;}});
const pendingWebSearch=sessionStorage.getItem('waypoint-web-search');if(pendingWebSearch)followWebSearch(pendingWebSearch).catch(e=>{if(e.message==='Web search not found')sessionStorage.removeItem('waypoint-web-search');notify(e.message);});

let webBatchRunning=false;
function renderWebBatch(batch){const panel=document.querySelector('#web-search-batch-results');panel.replaceChildren();for(const group of batch.groups){panel.append(element('h4',`Search: ${group.query} · page ${group.page || 1}`));if(group.error){panel.append(element('p',group.error,'review-label'));continue;}const data=group.data;panel.append(element('p',`${data.results.length} new candidates · ${data.results_examined} results examined${data.limited?' · provider results limited':''} · ${data.unresponsive_engines} engines unavailable`,'footnote'));for(const item of data.results)panel.append(webCandidate(item));}}
async function followWebBatch(batch){if(webBatchRunning)return;webBatchRunning=true;const stop=document.querySelector('#web-search-batch-cancel'),status=document.querySelector('#web-search-batch-status');stop.hidden=false;renderWebBatch(batch);try{for(;;){await new Promise(resolve=>setTimeout(resolve,1000));const result=await api('/api/web-search/batch-status',{task_id:batch.task});status.textContent=`${result.processed} of ${result.total} search pages completed.`;if(result.query){batch.groups.push({query:result.query,page:result.page,data:result.data,error:result.error});sessionStorage.setItem('waypoint-web-search-batch',JSON.stringify(batch));renderWebBatch(batch);}if(result.status==='complete'){sessionStorage.removeItem('waypoint-web-search-batch');status.textContent=`${result.cancelled?'Stopped':'Finished'}: ${result.processed} of ${result.total} search pages.${result.limit_reached?' Reached the 600-candidate limit.':''} Links remain unverified.`;break;}if(result.status==='failed'){sessionStorage.removeItem('waypoint-web-search-batch');throw new Error(result.error || 'Batch search failed');}}}finally{webBatchRunning=false;stop.hidden=true;}}
document.querySelector('#web-search-batch').addEventListener('submit',async event=>{event.preventDefault();if(webBatchRunning)return;const form=event.currentTarget,queries=form.elements.queries.value.split(/\r?\n/).map(q=>q.trim()).filter(Boolean);if(!queries.length || queries.length>10){notify('Enter 1 to 10 search phrases');return;}const button=form.querySelector('button[type=submit]');button.disabled=true;try{const provider=document.querySelector('#web-search').elements.provider.value;const pages=Number(form.elements.pages.value);if(!Number.isInteger(pages)||pages<1||pages>5)throw new Error('Choose 1 to 5 pages per phrase');const started=await api('/api/web-search/batch-start',{provider,queries,pages});const batch={task:started.task_id,groups:[]};sessionStorage.setItem('waypoint-web-search-batch',JSON.stringify(batch));await followWebBatch(batch);}catch(e){notify(e.message);}finally{button.disabled=false;}});
document.querySelector('#web-search-batch-cancel').addEventListener('click',async()=>{try{const batch=JSON.parse(sessionStorage.getItem('waypoint-web-search-batch') || 'null');if(batch)await api('/api/web-search/batch-cancel',{task_id:batch.task});}catch(e){notify(e.message);}});
try{const pending=JSON.parse(sessionStorage.getItem('waypoint-web-search-batch') || 'null');if(pending)followWebBatch(pending).catch(e=>{if(e.message==='Batch web search not found')sessionStorage.removeItem('waypoint-web-search-batch');notify(e.message);});}catch(_){sessionStorage.removeItem('waypoint-web-search-batch');}

function saveCandidateBatch(){if(candidateBatch)sessionStorage.setItem('waypoint-candidate-batch',JSON.stringify(candidateBatch));else sessionStorage.removeItem('waypoint-candidate-batch');}
function renderCandidateBatch(){const stop=document.querySelector('#candidate-batch-stop'),status=document.querySelector('#candidate-batch-status'),log=document.querySelector('#candidate-batch-log');stop.hidden=!candidateBatch;stop.disabled=Boolean(candidateBatch?.stop);if(candidateBatch){log.replaceChildren();status.textContent=`${candidateBatch.index} of ${candidateBatch.items.length} listings processed${candidateBatch.stop?' · stopping after the current page':''}.`;for(const event of candidateBatch.events)log.append(element('p',`${event.title}: ${event.message}`,'footnote'));}updateCandidateSelection();}
async function runCandidateBatch(){if(!candidateBatch || candidateBatchRunning)return;candidateBatchRunning=true;let failure=null;renderCandidateBatch();try{while(candidateBatch && candidateBatch.index<candidateBatch.items.length){const item=candidateBatch.items[candidateBatch.index];if(candidateBatch.stop && !candidateBatch.task)break;if(!candidateBatch.task){try{const endpoint=candidateBatch.phase==='check'?'/api/application-check/start':'/api/listing-inspect/start';const payload=candidateBatch.phase==='check'?{id:candidateBatch.job}:{url:item.url};const started=await api(endpoint,payload);candidateBatch.task=started.task_id;saveCandidateBatch();}catch(e){if(/active|finish the current|close or finish/i.test(e.message))throw e;candidateBatch.events.push({title:item.title,message:`Manual review: ${e.message}`});candidateBatch.index++;candidateBatch.phase='listing';candidateBatch.job=null;saveCandidateBatch();renderCandidateBatch();continue;}}let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api(candidateBatch.phase==='check'?'/api/application-check/status':'/api/listing-inspect/status',{task_id:candidateBatch.task});}while(result.status==='running');candidateBatch.task=null;if(candidateBatch.phase==='listing' && result.status==='complete'){candidateBatch.job=result.saved.id;candidateBatch.events.push({title:item.title,message:(result.saved.existing?'Listing already saved; review details.':'Listing saved; review extracted details.')+(result.capture && (!result.capture.saved || result.capture.complete===false)?' Original page capture is incomplete or unavailable.':'')+(result.capture?.structured_source && result.capture.structured_source!=='captured'?' Structured source was unavailable or exceeded the capture limit.':'')});if(candidateBatch.verify && !candidateBatch.stop){candidateBatch.phase='check';saveCandidateBatch();renderCandidateBatch();await refresh();continue;}}else if(candidateBatch.phase==='check' && result.status==='complete'){applicationChecks.set(candidateBatch.job,result.result);candidateBatch.events.push({title:item.title,message:result.result});}else candidateBatch.events.push({title:item.title,message:`Manual review: ${result.error || 'Inspection failed'}`});candidateBatch.index++;candidateBatch.phase='listing';candidateBatch.job=null;saveCandidateBatch();renderCandidateBatch();await refresh();}const stopped=candidateBatch.stop,done=candidateBatch.index,total=candidateBatch.items.length,events=candidateBatch.events;candidateBatch=null;saveCandidateBatch();document.querySelector('#candidate-batch-status').textContent=`${stopped?'Stopped':'Finished'}: ${done} of ${total} listings processed. Review extracted listings and application routes.`;const log=document.querySelector('#candidate-batch-log');log.replaceChildren();for(const event of events)log.append(element('p',`${event.title}: ${event.message}`,'footnote'));}catch(e){if(candidateBatch?.task && /not found/i.test(e.message)){candidateBatch.task=null;saveCandidateBatch();}failure=`Inspection paused: ${e.message}. Use Resume inspections to retry.`;}finally{candidateBatchRunning=false;renderCandidateBatch();if(failure)document.querySelector('#candidate-batch-status').textContent=failure;document.querySelector('#candidate-batch-start').textContent=candidateBatch?'Resume inspections':'Inspect selected listings';updateCandidateSelection();}}
document.querySelector('#candidate-batch-start').addEventListener('click',()=>{if(candidateBatch){void runCandidateBatch();return;}if(!selectedCandidates.size || selectedCandidates.size>10)return;candidateBatch={items:[...selectedCandidates.values()],index:0,phase:'listing',task:null,job:null,events:[],stop:false,verify:document.querySelector('#candidate-check-application').checked};saveCandidateBatch();void runCandidateBatch();});
document.querySelector('#candidate-batch-stop').addEventListener('click',()=>{if(!candidateBatch)return;candidateBatch.stop=true;saveCandidateBatch();renderCandidateBatch();if(!candidateBatchRunning)void runCandidateBatch();});
try{const pending=JSON.parse(sessionStorage.getItem('waypoint-candidate-batch') || 'null');if(pending && Array.isArray(pending.items) && pending.items.length>0 && pending.items.length<=10 && Number.isInteger(pending.index) && pending.index>=0 && pending.index<=pending.items.length && Array.isArray(pending.events)){candidateBatch=pending;for(let node=document.querySelector('#candidate-batch-status').parentElement;node;node=node.parentElement)if(node.tagName==='DETAILS')node.open=true;void runCandidateBatch();}else sessionStorage.removeItem('waypoint-candidate-batch');}catch(_){sessionStorage.removeItem('waypoint-candidate-batch');}

async function followListingInspection(id){let result;do{await new Promise(resolve=>setTimeout(resolve,1000));result=await api('/api/listing-inspect/status',{task_id:id});}while(result.status==='running');sessionStorage.removeItem('waypoint-listing-inspection');if(result.status!=='complete')throw new Error(result.error || 'Listing needs manual review');await refresh();const note=result.capture?.structured_source && result.capture.structured_source!=='captured'?' Structured source was unavailable or exceeded the capture limit.':'';notify((result.capture && (!result.capture.saved || result.capture.complete===false)?'Listing saved; original page capture is incomplete or unavailable.':result.saved.existing?'This listing is already saved.':result.job?.extraction==='local_model'?'Listing extracted locally; review the details and application route.':'Structured listing added; review it and its application route.')+note);}
const pendingListing=sessionStorage.getItem('waypoint-listing-inspection');if(pendingListing)followListingInspection(pendingListing).catch(e=>{if(e.message==='Listing inspection not found')sessionStorage.removeItem('waypoint-listing-inspection');notify(e.message);});

try{const pending=JSON.parse(sessionStorage.getItem('waypoint-form-navigation') || 'null');if(pending)followFormNavigation(pending.task,pending.job).catch(e=>{if(e.message==='Navigation task not found')sessionStorage.removeItem('waypoint-form-navigation');notify(e.message);});}catch(_){sessionStorage.removeItem('waypoint-form-navigation');}

const pendingTemplateEdit=sessionStorage.getItem('waypoint-template-edit');if(pendingTemplateEdit)followTemplateEdit(pendingTemplateEdit).then(async result=>{await refresh();notify(`${result.docx_name ? result.docx_name+' and ' : ''}${result.pdf_name} saved; inspect the PDF layout.`);}).catch(e=>{if(e.message==='Template edit not found')sessionStorage.removeItem('waypoint-template-edit');notify(e.message);});

try{const pending=JSON.parse(sessionStorage.getItem('waypoint-email-answer')||'null');if(pending && typeof pending.task==='string' && typeof pending.job==='string'){refresh().then(()=>{const job=state.jobs.find(row=>row.job.id===pending.job)?.job;if(job)showEmailDraft(job,pending.task);else notify('The job for the pending email draft is unavailable.');}).catch(error=>notify(`Could not recover email draft: ${error.message}`));}else if(pending)sessionStorage.removeItem('waypoint-email-answer');}catch(_){sessionStorage.removeItem('waypoint-email-answer');}

try{const pending=JSON.parse(sessionStorage.getItem('waypoint-draft') || 'null');if(pending)followDraft(pending.task,pending.job).catch(e=>{if(e.message==='Draft task not found')sessionStorage.removeItem('waypoint-draft');notify(e.message);});}catch(_){sessionStorage.removeItem('waypoint-draft');}

async function recoverReviewSession(){const panel=document.querySelector('#session-recovery');panel.replaceChildren(element('p','Checking the current review session…'));try{const result=await api('/api/form/session-status',{});reviewSessionChecked=true;const alreadyVisible=result.active&&activeReviewSession===result.session_id&&document.querySelector('#form-preview').childElementCount>0;activeReviewSession=result.active?result.session_id:null;panel.replaceChildren();if(result.active){try{const pending=JSON.parse(sessionStorage.getItem('waypoint-form-inspection')||'null');if(pending?.queued&&pending.job===result.job_id&&reviewQueue[0]===result.job_id){reviewQueue.shift();saveReviewQueue();sessionStorage.removeItem('waypoint-form-inspection');}}catch(_){}}if(result.active&&!alreadyVisible){panel.append(element('p','An application review is still open. Resume or close it before opening the next queued job.','review-label'));const resume=element('button','Resume current review'),close=element('button','Close current review');resume.type=close.type='button';resume.addEventListener('click',async()=>{resume.disabled=close.disabled=true;try{const started=await api('/api/form/rescan-start',{session_id:result.session_id});sessionStorage.setItem('waypoint-form-navigation',JSON.stringify({task:started.task_id,job:result.job_id}));await followFormNavigation(started.task_id,result.job_id);}catch(error){panel.append(element('p',error.message,'review-label'));resume.disabled=close.disabled=false;}});close.addEventListener('click',async()=>{resume.disabled=close.disabled=true;try{await api('/api/form/close',{session_id:result.session_id});activeReviewSession=null;panel.replaceChildren();renderReviewQueue();}catch(error){panel.append(element('p',error.message,'review-label'));resume.disabled=close.disabled=false;}});panel.append(resume,close);}renderReviewQueue();}catch(error){reviewSessionChecked=false;panel.replaceChildren(element('p',`Could not check the current review session: ${error.message}`,'review-label'));const retry=element('button','Retry session check');retry.type='button';retry.addEventListener('click',recoverReviewSession);panel.append(retry);renderReviewQueue();}}
recoverReviewSession();

async function recoverFormAnswer(){let pending;try{pending=JSON.parse(sessionStorage.getItem('waypoint-form-answer')||'null');}catch(_){sessionStorage.removeItem('waypoint-form-answer');return;}if(!pending || typeof pending.task!=='string')return;const panel=document.createElement('div');panel.setAttribute('aria-live','polite');panel.append(element('p','Recovering the pending answer draft…'));document.querySelector('#session-recovery').before(panel);try{let outcome;do{await new Promise(resolve=>setTimeout(resolve,1000));outcome=await api('/api/form/answer-status',{task_id:pending.task});}while(outcome.status==='running');sessionStorage.removeItem('waypoint-form-answer');if(outcome.status!=='complete')throw new Error(outcome.error || 'Draft failed');panel.replaceChildren(element('h3',`Recovered answer: ${pending.label || 'Application question'}`),element('p',outcome.answer.text),element('p','Review this draft and its sources. Inspect the current page again before using it; it has not been filled.','footnote'));for(const source of outcome.answer.sources)panel.append(element('p',`Source: ${source}`,'footnote'));}catch(error){if(error.message==='Answer draft not found')sessionStorage.removeItem('waypoint-form-answer');panel.replaceChildren(element('p',`Could not recover answer: ${error.message}`,'review-label'));}}
void recoverFormAnswer();
